import { Modal, Button, Box, Typography, IconButton, Alert } from "@mui/material";
import CloseIcon from "@mui/icons-material/Close";
import AddIcon from "@mui/icons-material/Add";
import { useContext, useEffect } from "react";
import { TeamsContext } from "../../../context/TeamsContext";
import TeamCard from "./teamCard";

const TeamsModal = ({ open, onClose, showAddTeam, setSelectedTeamId }) => {
  const { teams } = useContext(TeamsContext);
  
  const style = {
    position: "absolute",
    top: "50%",
    left: "50%",
    transform: "translate(-50%, -50%)",
    width: "100%",
    maxWidth: 1000,
    maxHeight: "90vh",
    bgcolor: "background.paper",
    borderRadius: "1rem",
    boxShadow: 24,
    p: { xs: 2, sm: 3, md: 4 },
    display: "flex",
    flexDirection: "column",
    gap: 2,
    overflowY: "auto",
    "&::-webkit-scrollbar": {
      width: "0.5em",
    },
    "&::-webkit-scrollbar-track": {
      backgroundColor: "rgba(0, 0, 0, 0.05)",
      borderRadius: "1em",
    },
    "&::-webkit-scrollbar-thumb": {
      backgroundColor: "rgba(99, 102, 241, 0.3)",
      borderRadius: "1em",
      "&:hover": {
        backgroundColor: "rgba(99, 102, 241, 0.5)",
      },
    },
  };

  useEffect(() => {
    setSelectedTeamId(null);
  }, [setSelectedTeamId]);

  return (
    <Modal open={open} onClose={onClose} closeAfterTransition>
      <Box sx={style}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 1,
          }}
        >
          <Typography variant="h5" sx={{ fontWeight: 700 }}>
            🏆 All Teams
          </Typography>
          <IconButton
            onClick={onClose}
            size="small"
            sx={{
              color: "text.secondary",
              "&:hover": {
                backgroundColor: "rgba(0, 0, 0, 0.05)",
              },
            }}
          >
            <CloseIcon />
          </IconButton>
        </Box>

        <Typography variant="body2" sx={{ color: "text.secondary", mb: 2 }}>
          {teams?.length === 0
            ? "No teams added yet. Create one to get started!"
            : `Showing ${teams?.length} team${teams?.length !== 1 ? "s" : ""}`}
        </Typography>

        {teams?.length > 0 ? (
          <Box
            sx={{
              display: "grid",
              gridTemplateColumns: {
                xs: "repeat(auto-fill, minmax(160px, 1fr))",
                sm: "repeat(auto-fill, minmax(200px, 1fr))",
                md: "repeat(auto-fill, minmax(220px, 1fr))",
              },
              gap: 2,
              mb: 3,
            }}
          >
            {teams
              ?.sort((a, b) => b.ranking - a.ranking)
              .map((team) => (
                <TeamCard
                  key={team.id}
                  team={team}
                  setSelectedTeamId={setSelectedTeamId}
                  showAddTeam={showAddTeam}
                />
              ))}
          </Box>
        ) : (
          <Alert severity="info" sx={{ borderRadius: "0.5rem", mb: 2 }}>
            <Typography variant="body2">
              Create your first team to start building team pairs!
            </Typography>
          </Alert>
        )}

        <Button
          variant="contained"
          color="secondary"
          startIcon={<AddIcon />}
          onClick={showAddTeam}
          fullWidth
          sx={{
            borderRadius: "0.5rem",
            py: 1.25,
            fontWeight: 600,
          }}
        >
          Add New Team
        </Button>
      </Box>
    </Modal>
  );
};

export default TeamsModal;
